def read_non_empty_lines(path):
    """逐行读取文本，跳过空白行，不把整个文件加载到内存。"""
    with open(path, "r", encoding="utf-8") as file:
        for line in file:
            text = line.strip()
            if text:
                yield text


def squares(numbers):
    for number in numbers:
        yield number * number


result = squares(range(4))
print(next(result))   # 0
print(list(result))   # [1, 4, 9]
print(list(result))   # []，生成器已经耗尽

